phases=[('truth','1. Establish the baseline','Versions, compatible contracts, actual policy bindings and full data flow.','R02, R03, R04, R07, R15'),('outcomes','2. Prove authorized outcomes','Fault-test writes, exact review, identity and staff ownership. Repair attribution and pagination.','R01, R05, R06, R10, R12, R16'),('measure','3. Measure chat and tools','Client-visible milestones joined with safe server, pack and provider traces.','R08, R13'),('speed','4. Improve the dominant wait','One experiment at a time; checkpoints and bounded concurrency under trust gates.','R09, R11'),('reuse','5. Generalize what is sound','Explicit domain policy, onboarding contracts and cross-department identity rules.','R14, R15')]
def gaphtml():
 out='<div class="interactive"><div class="controls"><label>Severity <select id="gap-severity"><option value="all">All priorities</option><option>High</option><option>Medium</option></select></label><label>Issue type <select id="gap-type"><option value="all">All types</option>'+''.join('<option>'+e(v)+'</option>' for v in ['Confirmed source defect','Design risk','Missing verification','Proposed improvement'])+'</select></label></div><p id="gap-count" aria-live="polite">16 gaps shown.</p><div class="gap-list">'
 for id,sev,typ,title,area,trigger,refs,fix,done,owner,dep,undo in gaps:
  out+=f'<details class="gap" data-severity="{e(sev)}" data-type="{e(typ)}"><summary><span class="gap-id">{id}</span><span><b>{e(title)}</b><small>{e(area)} · {e(typ)}</small></span><span class="priority">{sev}</span></summary><div class="gap-body"><p><b>Trigger and consequence.</b> {e(trigger)}</p><p><b>Proposed remedy.</b> {e(fix)}</p><p><b>Acceptance evidence.</b> {e(done)}</p><p><b>Suggested owner role.</b> {e(owner)}. <b>Depends on.</b> {e(dep)}.</p><p><b>Recovery or rollback.</b> {e(undo)}</p><p class="evidence">Source: '+citations(refs.split())+'</p></div></details>'
 return out+'</div></div>'
diagrams['roadmap']='<figure class="visual"><figcaption>Proposed dependency roadmap: no committed dates</figcaption><div class="roadmap">'+''.join('<button type="button" data-phase="'+k+'" aria-pressed="'+('true' if i==0 else 'false')+'"><b>'+e(t)+'</b><span>'+e(d)+'</span></button>' for i,(k,t,d,r) in enumerate(phases))+'</div><p id="phase-readout" class="readout" aria-live="polite">'+e(phases[0][1]+': '+phases[0][2]+' Related gaps: '+phases[0][3])+'.</p><p class="caption">These gates can overlap where independent. Reliability/privacy gates precede performance release decisions. Suggested role ownership needs explicit assignment.</p></figure>'
def inline(s):
 s=e(s)
 s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
 return s

def prose(s):
 return '\n'.join('<p>'+inline(p.replace('\n',' '))+'</p>' for p in s.strip().split('\n\n') if p.strip())
def citations(ids):
 return ' '.join('<a class="source-ref" href="#source-'+e(k)+'" aria-label="Source '+e(k)+': '+e(sources[k][0])+'">'+e(k)+'</a>' for k in ids)
