def bibliography():
 out='<ol class="source-list">'
 for key,(label,repo,sha,path,lines,url) in sources.items():
  title='<a href="'+e(url)+'" target="_blank" rel="noopener noreferrer">'+e(label)+'</a>' if url else e(label)
  out+='<li id="source-'+e(key)+'"><span class="source-id">'+e(key)+'</span>'+title+'<small>'+e(repo)+(' · snapshot '+e(sha) if sha else '')+'</small>'
  if path:out+='<code>'+e(path)+':'+e(lines)+'</code>'
  if not url:out+='<small>Local source pointer. Path and line metadata remain readable offline; the source file itself is not bundled.</small>'
  out+='</li>'
 return out+'</ol>'
